    stamp = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]

    five_cells = [(r, c) for r in range(r0, r1 + 1)
                  for c in range(c0, c1 + 1) if grid[r][c] == 5]
    anchor_r = sum(r for r, c in five_cells) // len(five_cells)
    anchor_c = sum(c for r, c in five_cells) // len(five_cells)

